  // INTRINSIC, OPTIONAL, PARAMETER, POINTER, SAVE, TARGET These are the ones
  // that have associated statements: ALLOCATE, DIMENSION, EXTERNAL, INTRINSIC,
  // OPTIONAL, PARAMETER, POINTER, SAVE, TARGET Attributes that are not an
  // associated statement: INTENT Paired statements: ALLOCATE, DEALLOCATE
