  //                       Header Code Declaration
  // ***********************************************************************
  // ***********************************************************************

  // Statement.setSubTreeFunctionPrototype ( "HEADER",
  // "../Grammar/sageCommon.code" ); Statement.excludeFunctionPrototype    (
  // "HEADER", "../Grammar/sageCommon.code" );

  Statement.setFunctionPrototype("HEADER", "../Grammar/Statement.code");

  // DQ (12/30/2009): Added post declaration support for the template function
  // StatementReplace which was previously buried into the generated source code
  // and which work only when all the references were in the same file.  Now
  // with the new support to build smaller ROSETTA generated files this template
  // function must be put into the header file where all the different source
  // code files can see it defined.
  Statement.setPostdeclarationString("HEADER_STATEMENT_POSTDECLARATION",
                                     "../Grammar/Statement.code");

  // MK: the following two function calls could be wrapped into a single one:
  Statement.setFunctionPrototype("HEADER_POST_CONSTRUCTION_INITIALIZATION",
                                 "../Grammar/Statement.code");
  Statement.setSubTreeFunctionPrototype(
      "HEADER_POST_CONSTRUCTION_INITIALIZATION", "../Grammar/Statement.code");

  // DQ (12/4/2004): Now we automate the generation of the destructors
  // Statement.setAutomaticGenerationOfDestructor(false);

  // Statement.excludeFunctionPrototype    (
  // "HEADER_POST_CONSTRUCTION_INITIALIZATION",
  //                                         "../Grammar/Statement.code" );
  // Statement.setDataPrototype    ( "SgStatement*","parent","= NULL");
  // Statement.excludeDataPrototype( "SgStatement*","parent","= NULL");

  // The functions we want to generate for setting the parent data are special
  // Statement.setAutomaticGenerationOfDataAccessFunctions(false);

  // DQ (3/21/2007): Added numeric label to support Fortran (any statement can
  // have a label) A value of -1 indicates that no label is explicit in the
  // source code. Statement.setDataPrototype("int", "numeric_label", "= -1",
  //           NO_CONSTRUCTOR_PARAMETER, BUILD_ACCESS_FUNCTIONS, NO_TRAVERSAL,
