  // DQ (10/10/2006): Use the SgQualifiedNamePtrList instead of a boolean
  // value, and remove this data member. DQ (9/7/2004): Moved to declaration
  // from variable declarations DQ (9/4/2004): Added support for
  // qualification of type names in variable declarations

  // DQ (9/23/2004): Removed this since it is better to compute the qualified
  // name dynamically than to have it statically specified in the AST and
  // possibly set incorrectly after a possible transformation.  This also
  // simplifies the transformations since they don't have to worry about
  // setting this correctly. DQ (9/7/2004): Moved to declaration from
  // variable declarations DQ (9/6/2004): Instead of storing the name store a
  // symbol (either a SgClassSymbol or SgNamespaceSymbol), since this can be
  // a cascading set of names (as in A::B::C::x) we need to store a list of
  // these name qualifiers. As long as the traversal does not traverse the
  // list then we can put it into the current IR node.  This would have to be
  // moved to its own IR node if we later want to traverse it!  Until we have
  // an example of this implemented we will use a list of SgSymbols and later
  // move it to a new IR node where it can be used more generally in variable
  // declarations, initializers, base class specifiers, global and member
  // functions and tose in namespaces, etc.

  // DQ (9/23/2004): Added support for references to the defining declaration
  // (all others are forward or non-defining) as in the following declaration
  // of a typedef of a function pointer:
  //      typedef struct foobar *(*foobarFunctionPointer)();
  // where the "struct foobar" is not not really a forward declaration in a
  // typical sense (it is the base type of a pointer which is a function
  // return type), but not a defining declaration either! Having a concept of
  // a "defining declaration" allows us to simplify the unparser and more
  // accurately know when to output a definition.  The idea is not specific
  // to class declarations and perhaps should be in the SgDeclaration object.
  DeclarationStatement.setDataPrototype(
      "SgDeclarationStatement*", "definingDeclaration", "= NULL",
      NO_CONSTRUCTOR_PARAMETER, NO_ACCESS_FUNCTIONS, NO_TRAVERSAL, NO_DELETE);

  // DQ (9/23/2004): Keep track of the first non-defining declaration (so it
  // can be reused to avoid redundant declarations (explicitly or implicitly
  // forward declarations).
  DeclarationStatement.setDataPrototype(
      "SgDeclarationStatement*", "firstNondefiningDeclaration", "= NULL",
      NO_CONSTRUCTOR_PARAMETER, NO_ACCESS_FUNCTIONS, NO_TRAVERSAL, NO_DELETE);

  // DQ (10/10/2006): Not all declarations make sense with qualified names,
  // but enough do that I have placed this here for now! I have removed these
  // lists from the SgNamedType IR nodes since SgTypes are shared and name
  // qualification is require non-uniformally within the AST (making share IR
  // nodes holding name qualification list a problem).
  DeclarationStatement.setDataPrototype(
      "SgQualifiedNamePtrList", "qualifiedNameList", "",
      NO_CONSTRUCTOR_PARAMETER, NO_ACCESS_FUNCTIONS, NO_TRAVERSAL, NO_DELETE);

  // DQ (11/23/2007): In Fortran, we now support the bind attribute (fixed to
  // be handled on the DeclarationStatement instead of separately on
  // SgFunctionDeclaration, SgVariableDeclaration, and SgClassDeclaration IR
  // nodes). Use the "linkage" string already stored in the
  // SgDeclarationStatement (above).
  DeclarationStatement.setDataPrototype(
      "std::string", "binding_label", "=\"\"", NO_CONSTRUCTOR_PARAMETER,
      BUILD_ACCESS_FUNCTIONS, NO_TRAVERSAL, NO_DELETE);
  DeclarationStatement.setDataPrototype(
      "bool", "binding_cdefined", "= false", NO_CONSTRUCTOR_PARAMETER,
      BUILD_ACCESS_FUNCTIONS, NO_TRAVERSAL, NO_DELETE);

  // DQ (7/17/2017): Adding support for a new concept of declaration scope (see
  // documentation above).
  DeclarationStatement.setDataPrototype(
      "SgDeclarationScope*", "declarationScope", "= NULL",
      NO_CONSTRUCTOR_PARAMETER, BUILD_ACCESS_FUNCTIONS, NO_TRAVERSAL,
      NO_DELETE);

  // A non-function declarator can introduce one or more source-written tags
  // below pointer, array, or function-type layers (for example,
  // `struct A *(*f)(struct B *)`).  Those declarations have the surrounding
  // lexical scope as their semantic symbol scope, but the exact declarator is
  // their physical source owner.  Model that ownership directly instead of
  // publishing the tags as standalone declarations or leaving them detached.
  // Function declarations retain their more specialized
  // function_declarator_scope because it also owns parameter-name semantics.
  DeclarationStatement.setDataPrototype(
      "SgDeclarationScope*", "source_declarator_scope", "= NULL",
      NO_CONSTRUCTOR_PARAMETER, BUILD_ACCESS_FUNCTIONS, DEF_TRAVERSAL,
      DEF_DELETE, COPY_DATA, OPTIONAL_TRAVERSAL_MEMBER);

