  // We would like to have a class include data members which are
  // terminals/nonterminals within the grammar. In the case where these are X
  // terminals/nonterminals the data members should be X versions of these.
  // It is difficult for it to be either the X or non_X version since these
  // are different types. There are three cases to consider:
  //   1) Data member is an X version (matching Xness of the outer
  //   AstNodeClass)
  //           Implementation proceedure: build X version
  //   2) Data member is a non X version (not matching the Xness of the outer
  //   AstNodeClass)
  //           Implementation proceedure: build non X version
  //   3) Data member can be the X OR non X version (independent of the Xness
  //   of the outer AstNodeClass)
  //           Implementation proceedure: build X and non X versions?

  // In this case we want the Xness of the data member to match that of the
  // outer AstNodeClass
  FunctionDeclaration.setDataPrototype(
      "SgFunctionType*", "type", "= NULL", CONSTRUCTOR_PARAMETER,
      BUILD_ACCESS_FUNCTIONS, NO_TRAVERSAL, NO_DELETE);

  // DQ (4/18/2005): Removed this data member since it is redundent with the
  // firstNondefiningDeclaration in the base class (SgDeclarationStatement)
  // QY: need forward definition so that we can set definition pointer as
  // NULL for forward decls
  FunctionDeclaration.setDataPrototype(
      "SgFunctionDefinition*", "definition", "= NULL", CONSTRUCTOR_PARAMETER,
      BUILD_ACCESS_FUNCTIONS, DEF_TRAVERSAL, NO_DELETE, COPY_DATA,
      OPTIONAL_TRAVERSAL_MEMBER);

