  // DQ (3/4/2007): We want to force the copy mechanism to skip building a new
  // SgCtorInitializerList when making a copy (use NO_COPY_DATA to do this). The
  // p_CtorInitializerList is handled internally in SageIII. DQ (11/16/2004):
  // Remove this since it is redundent with the scope data member for a function
  // (which a member function inherits! This will of course effect the number of
  // parameters for the constructor (I hope that that will not be too drastic a
  // change). If this is a drastic change then we can include this and remove it
  // later. Iteratively! MemberFunctionDeclaration.setDataPrototype (
  // "SgClassDefinition*", "scope", "= NULL",
  //                CONSTRUCTOR_PARAMETER, BUILD_ACCESS_FUNCTIONS, NO_TRAVERSAL,
  //                NO_DELETE);
  // MemberFunctionDeclaration.setDataPrototype ( "SgCtorInitializerList*",
