  // DQ (9/4/2004): Added support for qualification of type names in variable
  // declarations VariableDeclaration.setDataPrototype("bool",
  // "need_name_qualifier", "= false",
  //                              NO_CONSTRUCTOR_PARAMETER,
  //                              BUILD_ACCESS_FUNCTIONS, NO_TRAVERSAL,
  //                              NO_DELETE);

  // DQ (10/5/2004): This was decided against, qualified names are now generated
  // on the fly as required, which results in a more robust mechanism. DQ
  // (9/6/2004): Instead of storing the name store a symbol (either a
  // SgClassSymbol or SgNamespaceSymbol), since this can be a cascading set of
  // names (as in A::B::C::x) we need to store a list of these name qualifiers.
  // As long as the traversal does not traverse the list then we can put it into
  // the current IR node.  This would have to be moved to its own IR node if we
  // later want to traverse it!  Until we have an example of this implemented we
  // will use a list of SgSymbols and later move it to a new IR node where it
  // can be used more generally in variable declarations, initializers, base
  // class specifiers, global and member functions and tose in namespaces, etc.
  // VariableDeclaration.setDataPrototype("string", "name_qualifier", "",
  //             NO_CONSTRUCTOR_PARAMETER, BUILD_ACCESS_FUNCTIONS, NO_TRAVERSAL,
  //             NO_DELETE);
  // VariableDeclaration.setDataPrototype("SgSymbolPtrList",
  // "name_qualifier_list", "",
  //                              NO_CONSTRUCTOR_PARAMETER,
  //                              BUILD_ACCESS_FUNCTIONS, NO_TRAVERSAL,
  //                              NO_DELETE);

  // DQ (10/5/2004): Eplicitly record if the base type of this variable
  // declaration is to be output. This is part of the support for defining vs.
  // non-defining declarations but all types are shared and the declaration is
  // hidden in the type so we must specify external to the type if the full type
  // definition is to be output or not and we have to do it in the variable
  // declaration instead of the type.  This is also called autonomous
  // declaration handling.  The following examples make clear the definition of
  // autonomous and non autonomous declarations:
  //      struct A { int i; };         // autonomous declaration
  //      struct B { int i; } b;       // non autonomous declaration
  // Clearly the autonomous case is the more common, but we must handle both.
  // Since all types and many declarations are shared we can't store such
  // information in the types or declarations. Although we provide for defining
  // and non-defining declarations, the declarations are stored in the type and
  // the type is always shared so we are forced to makr the variable declaration
  // as containing a type to be output with full definition.  Note that this is
  // not the same concept as "type elaboration" which is the use of the keyword
  // "class" before variable names (used to distinguish them from functions
  // since within C++ both functions and variables can co-exist with the same
  // name in the same scope). VariableDeclaration.setDataPrototype("bool",
  // "contains_non_autonomous_declaration", "= false",
  //             NO_CONSTRUCTOR_PARAMETER, BUILD_ACCESS_FUNCTIONS, NO_TRAVERSAL,
  //             NO_DELETE);
  // DQ (5/9/2005): Adding special template support.  These data members help
  // control the instantiation of templates and there representation in the
  // unparsed code (code generated by ROSE). Note that the File_Info object is
  // where IR nodes are marked as compiler generated (also relavant here).
  VariableDeclaration.setDataPrototype(
      "SgDeclarationStatement::template_specialization_enum", "specialization",
      "= SgDeclarationStatement::e_no_specialization", NO_CONSTRUCTOR_PARAMETER,
      BUILD_ACCESS_FUNCTIONS, NO_TRAVERSAL, NO_DELETE);
  VariableDeclaration.setDataPrototype(
      "unsigned int", "explicitTemplateSpecializationHeaderCount", "= 0",
      NO_CONSTRUCTOR_PARAMETER, BUILD_ACCESS_FUNCTIONS, NO_TRAVERSAL,
      NO_DELETE);

  // DQ (11/15/2004): class declarations for nested classes can appear
  // outside the scope of the class to which they belong, thus the parent
  // information is not sufficent to define the relationship of nested
  // classes (and typedefs within the classes, as well, which is the current
  // bug in Kull).  So we need an additional data member to explicitly
  // represent the scope of a class (consistant with the design of the member
  // function declaration).

  // DQ (8/20/2006): Record if global name qualification is required on the
  // type. See test2003_01.C for an example of where this is required.
  VariableDeclaration.setDataPrototype(
      "bool", "requiresGlobalNameQualificationOnType", "= false",
      NO_CONSTRUCTOR_PARAMETER, NO_ACCESS_FUNCTIONS, NO_TRAVERSAL, NO_DELETE);

