  // DQ (1/20/2014): This must be a SgValueExp, it is a constant expression ROSE
  // uses a SgValueExp for this). It is usually a SgUnsignedLongVal, but it can
  // sometimes be a SgIntVal.  I wonderif it could be a cast (SgCastExp) at some
  // point.  For now we need to change this to be at least a SgValueExp instead
  // of a SgUnsignedLongVal. We need to reepresent it in the AST as an
  // expression so that we can record the original expression tree from which it
  // was computed.  This is required where the expression contains the sizeof
  // operator applied to machine dependent types (see test2014_48.c for an
  // example of this).  This is a problem when ROSE is using the -m32 mode. Note
  // that test2012_166.c demonstrates that this can be a SgIntVal expresion. It
  // is hard to believe that the "SgUnsignedLongVal" should not be an "int"
  // instead! VariableDefinition.setDataPrototype ( "SgUnsignedLongVal*",
  // "bitfield", "= NULL",
