  // DQ (3/10/2007): Moved to appear at the end of the class and changed to be a
  // boolean type
  ClassDeclaration.setDataPrototype(
      "bool", "from_template", "= false", NO_CONSTRUCTOR_PARAMETER,
      BUILD_ACCESS_FUNCTIONS, NO_TRAVERSAL, NO_DELETE);

  // DQ (3/10/2007): Moved to appear at the end of the class
  // DQ (12/14/2005): Where a class is referenced before it is build (common in
  // name qualified types using templates) we have to build the SgClassSymbol
  // and so the SgClassDeclaration too early to know where the class is defined
  // (so we can't know the scope yet).  In this case we don't want to leave the
  // scope pointer NULL since this is indistinguishable from an error.  So we
  // build a field value that indicates that the we did the best we could and we
  // will fixup the pointer when the defining declaration is built. The
  // semantics if the AST is that this is only true for a period of time during
  // the construction of the Sage AST. It should be tested in the AST
  // consistancy tests.
  ClassDeclaration.setDataPrototype(
      "bool", "fixupScope", "= false", NO_CONSTRUCTOR_PARAMETER,
      BUILD_ACCESS_FUNCTIONS, NO_TRAVERSAL, NO_DELETE);

  // DQ (3/10/2007): Added to support un-named constructions (specifically for
  // SgClassDeclaration and SgEnumDeclaration) Note that un-named declarations
  // are assigned a name, for at least internal use, but that the code
  // generation phase has to be extra careful about using those names (e.g.
  // never in a typedef, and only where more than one variable was declared in
  // in a SgVariableDeclaration, this later pointe can be difficult to
  // distinguish because we currently normalize the case of multiple variables
  // in a single variable declaration.
  ClassDeclaration.setDataPrototype(
      "bool", "isUnNamed", "= false", NO_CONSTRUCTOR_PARAMETER,
      BUILD_ACCESS_FUNCTIONS, NO_TRAVERSAL, NO_DELETE);

